<?php
final class LoanView {
    public static function render(PDO $db,int $id): string {
        $s=$db->prepare('SELECT l.*,p.full_name FROM loans l JOIN participants p ON p.id=l.participant_id WHERE l.id=?');$s->execute([$id]);$loan=$s->fetch();if(!$loan)return '<section class="card"><h1>Préstamo no encontrado</h1></section>';
        $s=$db->prepare('SELECT * FROM loan_installments WHERE loan_id=? ORDER BY installment_number');$s->execute([$id]);$rows=$s->fetchAll();$total=array_sum(array_column($rows,'total_amount'));$paid=array_sum(array_column($rows,'paid_amount'));
        $html='<section class="hero"><span>PLAN DE PAGOS</span><h1>Plan de pagos #'.(int)$id.'</h1><p>'.htmlspecialchars($loan['full_name']).' · Capital inicial $'.number_format($loan['principal'],0,',','.').' · Tasa '.($loan['monthly_rate']*100).'% mensual</p></section><div class="stats"><article class="card"><small>Capital inicial</small><strong>$'.number_format($loan['principal'],0,',','.').'</strong></article><article class="card"><small>Total del plan</small><strong>$'.number_format($total,0,',','.').'</strong></article><article class="card"><small>Total pagado</small><strong>$'.number_format($paid,0,',','.').'</strong></article></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Vencimiento</th><th>Capital amortizado</th><th>Interés fijo</th><th>Cuota</th><th>Pagado</th><th>Estado / Acción</th></tr></thead><tbody>';
        foreach($rows as $r){$complete=(float)$r['paid_amount'] >= (float)$r['total_amount'];$html.='<tr><td>'.$r['installment_number'].'</td><td>'.$r['due_date'].'</td><td>$'.number_format($r['principal_amount'],2,',','.').'</td><td>$'.number_format($r['interest_amount'],2,',','.').'</td><td>$'.number_format($r['total_amount'],2,',','.').'</td><td>$'.number_format($r['paid_amount'],2,',','.').'</td><td>'.($complete?'<span class="badge">Pagada</span>':'<form method="post"><input type="hidden" name="action" value="installment"><input type="hidden" name="installment_id" value="'.$r['id'].'"><input name="amount" type="number" step="0.01" min="0" placeholder="Abono"><button>Guardar pago</button></form>').'</td></tr>';}
        return $html.'</tbody></table></div>';
    }
}
